Käärmepelin koodaaminen C:llä, joka käyttää kuvia koko tason animointiin, vaatii hieman enemmän työtä kuin perusversio, mutta se on mahdollista. Tässä on yksinkertainen esimerkki, jossa käytetään NCURSES-kirjastoa, joka on yleisesti käytetty kirjasto tekstinpohjaisten pelien kehittämiseen.

Ennen kuin aloitat, varmista, että sinulla on NCURSES-kirjasto asennettuna. Useimmissa Linux-jakelupaketeissa se on saatavilla pakettienhallinnan kautta. Esimerkiksi Ubuntu/Debian-pohjaisissa jakelupaketeissa voit asentaa sen seuraavalla komennolla:

```bash
sudo apt-get update
sudo apt-get install libncurses5-dev
```

Tässä on yksinkertainen esimerkki käärmepelistä, joka käyttää NCURSESia:

```c
#include <ncurses.h>

// Käärmeen rakenteen määrittely
typedef struct {
    int x, y; // Käärmeen pään koordinaatit
    int pituus; // Käärmeen pituus
    int suunta; // Käärmeen liikkeen suunta (ylös, alas, vasen, oikea)
} Snake;

// Pelin tilan määrittely
typedef struct {
    int x, y; // Hedelmän sijainti
    int score; // Pelaajan pisteet
    Snake snake;
} Game;

// Funktio käärmeen piirtämiseen
void draw_snake(Game *game) {
    for (int i = 0; i < game->snake.pituus; i++) {
        mvaddch(game->snake.x + i % 20, game->snake.y + i / 20, 'O');
    }
}

// Pääfunktio
int main() {
    initscr(); // NCURSESin alustus
    cbreak(); // Poista enter-näppäimen odotus
    noecho(); // Piilota näppäimistön syöte
    curs_set(FALSE); // Piilota kursori

    // Aloita peli
    Game game;
    game.snake.x = 10;
    game.snake.y = 10;
    game.snake.pituus = 5;
    game.snake.suunta = RIGHT;
    game.x = 15;
    game.y = 15;
    game.score = 0;

    while (1) {
        // Piirrä peli
        erase();
        mvaddch(game.x, game.y, '@');
        draw_snake(&game);

        // Tarkista syöte
        int ch = getch();
        if (ch == 'q') break;

        // Liikuta käärmettä
        switch (ch) {
            case KEY_UP:
                if (game.snake.suunta != DOWN) game.snake.suunta = UP;
                break;
            case KEY_DOWN:
                if (game.snake.suunta != UP) game.snake.suunta = DOWN;
                break;
            case KEY_LEFT:
                if (game.snake.suunta != RIGHT) game.snake.suunta = LEFT;
                break;
            case KEY_RIGHT:
                if (game.snake.suunta != LEFT) game.snake.suunta = RIGHT;
                break;
        }

        // Päivitä käärmeen sijainti
        switch (game.snake.suunta) {
            case UP:
                game.snake.x--;
                break;
            case DOWN:
                game.snake.x++;
                break;
            case LEFT:
                game.snake.y--;
                break;
            case RIGHT:
                game.snake.y++;
                break;
        }

        // Tarkista, osuiko käärme itseensä tai reunoihin
        if (game.snake.x < 0 || game.snake.x >= 20 || game.snake.y < 0 || game.snake.y >= 20) {
            break;
        }
        for (int i = game.snake.x; i < game.snake.x + game.snake.pituus; i++) {
            if (i < 0 || i >= 20 || game.snake.y + (i - game.snake.x) / 20 < 0 || game.snake.y + (i - game.snake.x) / 20 >= 20) {
                break;
            }
            if (i >= game.snake.pituus && game.snake.x + (i - game.snake.pituus) == game.snake.x && game.snake.y + (i - game.snake.pituus) / 20 == game.snake.y + (i - game.snake.x) / 20) {
                break;
            }
            if (game.snake.x + (i - game.snake.x) == game.x && game.snake.y + (i - game.snake.x) / 20 == game.y + (i - game.snake.x) / 20) {
                game.snake.pituus++;
                game.score++;
                break;
            }
        }

        // Odota hetki ennen seuraavaa liikettä
        refresh();
        delay(100);
    }

    endwin(); // NCURSESin lopetus

    return 0;
}
```

Tämä koodi luo yksinkertaisen käärmepelin, jossa käärme liikkuu näppäimistön avulla ja syö hedelmiä. Hedelmä ilmestyy satunnaisesti ruudulle, ja kun käärme syö sen, sen pituus kasvaa ja pisteet lisääntyvät.

